-- 40 bilingual demo listings, eight in each of five storefront categories.
insert into public.categories(slug,name_en,name_ar) values
('pc-accessories','PC Accessories','ملحقات الكمبيوتر'),('games','Games & Gift Cards','الألعاب وبطاقات الهدايا'),('pc-builds','PC Components','مكونات الكمبيوتر'),('phones','Phones','الهواتف'),('phone-accessories','Phone Accessories','ملحقات الهاتف')
on conflict(slug) do update set name_en=excluded.name_en,name_ar=excluded.name_ar;
with names as (
 select 'pc-accessories' slug, unnest(array['PixelForge Mechanical Keyboard','Arc Mouse Pro','Neon XL Mousepad','Pulse Studio Headset','StreamCam HD Webcam','Vox USB Microphone','Link Braided Cable','Arc Wireless Controller']) en, unnest(array['لوحة مفاتيح ميكانيكية','فأرة آرك برو','لوحة ماوس نيون','سماعة بالس ستوديو','كاميرا ستريم كام','ميكروفون فوكس','كابل لينك مضفر','يد تحكم آرك لاسلكية']) ar, unnest(array[18500,32000,12500,41000,28000,36000,7500,24000])::numeric price, unnest(array[18500,36800,12500,41000,32200,36000,7500,27600])::numeric old
 union all select 'games', unnest(array['Starbound PC Key','Neon Drift Deluxe','Kingdoms of Ash','Rift Runner 2','PlayStation Store Card','Xbox Game Pass Card','Steam Wallet Code','Pixel Quest Collection']), unnest(array['مفتاح ستاربوند للكمبيوتر','نيون دريفت ديلوكس','ممالك الرماد','ريفت رنر ٢','بطاقة بلايستيشن','بطاقة إكس بوكس','رصيد ستيم','مجموعة بيكسل كويست']), unnest(array[22000,36000,28000,41000,25000,32000,20000,52000])::numeric, unnest(array[22000,41400,28000,41000,28750,32000,23000,52000])::numeric
 union all select 'pc-builds', unnest(array['Forge B650 Motherboard','Photon RTX 4060 GPU','Core i5 14400F CPU','16GB DDR5 Memory Kit','1TB NVMe SSD','650W Bronze PSU','Airflow Mid Tower Case','Frost 240 Liquid Cooler']), unnest(array['لوحة فورج B650','بطاقة فوتون RTX 4060','معالج كور i5 14400F','ذاكرة DDR5 سعة 16 جيجابايت','قرص NVMe سعة 1 تيرابايت','مزود طاقة برونزي 650 واط','صندوق متوسط بتهوية','مبرد مائي فروست 240']), unnest(array[37000,288000,165000,42000,38000,34000,62000,78000])::numeric, unnest(array[42550,288000,189750,42000,43700,34000,62000,89700])::numeric
 union all select 'phones', unnest(array['Nova X Pro 256GB','Orbit S 128GB','Pixel One 256GB','Nova Lite 128GB','Galaxy A55 256GB','iPhone 15 128GB','Rift Phone 12 256GB','Orbit Flip 256GB']), unnest(array['نوفا إكس برو ٢٥٦ جيجابايت','أوربت إس ١٢٨ جيجابايت','بيكسل ون ٢٥٦ جيجابايت','نوفا لايت ١٢٨ جيجابايت','جالاكسي A55 ٢٥٦ جيجابايت','آيفون ١٥ ١٢٨ جيجابايت','ريفت فون ١٢ ٢٥٦ جيجابايت','أوربت فليب ٢٥٦ جيجابايت']), unnest(array[980000,620000,870000,440000,790000,1450000,890000,1320000])::numeric, unnest(array[1127000,620000,1000500,506000,908500,1450000,1023500,1320000])::numeric
 union all select 'phone-accessories', unnest(array['Armor Case — Clear','65W Fast Charger','USB-C Braided Cable','Tempered Glass Duo','Power Bank 20000mAh','Wave Buds Wireless','MagSafe Wallet Stand','Car Charge Dock']), unnest(array['غطاء آرمور شفاف','شاحن سريع ٦٥ واط','كابل يو إس بي سي مضفر','واقي شاشة زجاجي مزدوج','بطارية متنقلة ٢٠٠٠٠ مللي أمبير','سماعات ويف لاسلكية','حامل ومحفظة ماج سيف','قاعدة شحن للسيارة']), unnest(array[9500,22000,5500,6000,32000,45000,18000,19500])::numeric, unnest(array[11000,25300,5500,6900,36800,45000,20700,19500])::numeric
), numbered as (select *,row_number() over(partition by slug order by en)::int n from names)
insert into public.products(slug,category_id,subcategory,brand,name_en,name_ar,description_en,description_ar,price,old_price,stock,rating,badges,images,variants,specs,tags,featured,is_active)
select lower(regexp_replace(en,'[^a-zA-Z0-9]+','-','g')),c.id,en,case x.slug when 'phones' then (array['Nova','Orbit','Pixel','Galaxy'])[n%4+1] when 'games' then (array['Pixel Arcade','Steam','PlayStation','Xbox'])[n%4+1] else (array['PIXELFORGE','NOVA','ORBIT','NEON LABS'])[n%4+1] end,en,ar,'Built for dependable everyday performance. Tested, packed and ready to ship from Pixel Store.','منتج موثوق للاستخدام اليومي، جاهز للشحن من متجر بيكسل.',price,case when old>price then old else null end,case when n=8 then 0 else 4+n*2 end,4.6,case when n=1 then array['NEW']::text[] when n=3 then array['DEAL']::text[] else array[]::text[] end,array[]::text[],jsonb_build_array(jsonb_build_object('name','Color','values',jsonb_build_array('Black','White'),'prices',jsonb_build_array(0,0),'stock',jsonb_build_array(4,3))),jsonb_build_object('Category',c.name_en,'Warranty','12 months') || case x.slug when 'phones' then jsonb_build_object('RAM',(array['8GB','12GB','16GB'])[n%3+1],'Storage',(array['128GB','256GB','512GB'])[n%3+1],'Color',(array['Midnight','Silver','Ocean'])[n%3+1]) when 'games' then jsonb_build_object('Platform',(array['PC','PlayStation','Xbox'])[n%3+1],'Genre',(array['Action','Racing','Adventure','RPG'])[n%4+1]) when 'phone-accessories' then jsonb_build_object('Compatible',(array['Universal','iPhone 15','Galaxy S24'])[n%3+1],'Type',(array['Case','Charger','Audio','Power'])[n%4+1]) when 'pc-accessories' then jsonb_build_object('Type',(array['Keyboard','Mouse','Audio','Streaming'])[n%4+1],'Connection',case when n%2=0 then 'Wired' else 'Wireless' end) when 'pc-builds' then jsonb_build_object('Type',(array['Motherboard','Graphics','Processor','Memory','Storage','Power','Case','Cooling'])[n],'Socket',case when n%2=0 then 'AM5' else 'LGA1700' end) else '{}'::jsonb end,array[lower(c.name_en)],n<=2,true from numbered x join public.categories c using(slug)
on conflict(slug) do update set name_en=excluded.name_en,name_ar=excluded.name_ar,category_id=excluded.category_id,price=excluded.price,old_price=excluded.old_price,stock=excluded.stock,is_active=true;
update public.products p set category_id=c.id,subcategory='Steam Accounts',brand='Steam',name_en='Steam Account — Meccha Chameleon',name_ar='حساب ستيم — Meccha Chameleon',description_en='Steam account that includes Meccha Chameleon.',description_ar='حساب ستيم يتضمن لعبة Meccha Chameleon.',price=300,stock=12,rating=0,badges=array['NEW']::text[],images=array['assets/chameleon-cover.jpg']::text[],variants='[]'::jsonb,specs='{"Platform":"Steam","Game":"Meccha Chameleon","Type":"Game account"}'::jsonb,tags=array['steam','account','meccha','chameleon']::text[],featured=true,is_active=true
from public.categories c where p.slug='steam-account-meccha-chameleon' and c.slug='games';
insert into public.products(slug,category_id,subcategory,brand,name_en,name_ar,description_en,description_ar,price,stock,rating,badges,images,variants,specs,tags,featured,is_active)
select 'steam-account-meccha-chameleon',c.id,'Steam Accounts','Steam','Steam Account — Meccha Chameleon','حساب ستيم — Meccha Chameleon','Steam account that includes Meccha Chameleon.','حساب ستيم يتضمن لعبة Meccha Chameleon.',300,12,0,array['NEW']::text[],array['assets/chameleon-cover.jpg']::text[],'[]'::jsonb,'{"Platform":"Steam","Game":"Meccha Chameleon","Type":"Game account"}'::jsonb,array['steam','account','meccha','chameleon']::text[],true,true
from public.categories c where c.slug='games' and not exists(select 1 from public.products p where p.slug='steam-account-meccha-chameleon');
